import { QUOTES } from './quotes.js'
import { DICT } from './dictionary.js'
import { describesEnvironment } from './environmentNarration.js'
export { DICT } from './dictionary.js'
export { describesEnvironment } from './environmentNarration.js'

// ---------------------------------------------------------------------------
// TOKEN HELPERS
//   w(id)            -> word token, uses the dictionary surface/gloss
//   wf(id, al, en?)  -> word token with an inflected surface (same sense id)
//   p(en)            -> structural token (punctuation), rendered plainly, not discoverable
// ---------------------------------------------------------------------------
export const w = (id) => {
  const entry = DICT[id]
  if (!entry) throw new Error(`w('${id}'): unknown dictionary sense`)
  return {
    id,
    al: entry.al,
    en: entry.en,
    formTag: entry.forms?.find((form) => form.al.toLowerCase() === entry.al.toLowerCase())?.tag,
  }
}
// The declared English senses of a word: enAll ("on / in") split into a set, or
// just [en] for single-sense words.
const sensesOf = (id) => (DICT[id].enAll ?? DICT[id].en).split('/').map((s) => s.trim())
// The inflected surfaces a word's forms table declares (lower-cased). Used by wf()
// to guarantee every surface the STORY shows is also a known form — so the forms
// table (the single source of truth for a word's declension) can never fall out of
// sync with the story. Case-folded so sentence-initial Capitals match; diacritics
// stay significant so a missing ë is caught as the real typo it is.
const formSurfaces = (id) => (DICT[id].forms ?? []).map((f) => f.al.toLowerCase())
export const wf = (id, al, en) => {
  if (!DICT[id]) throw new Error(`wf('${id}', '${al}'): unknown dictionary sense`)
  // If a word declares multiple senses (enAll), a per-token gloss override must
  // pick one of them — guards against typos and senses drifting out of enAll.
  // (Words without enAll keep using `en` freely for inflected-form glosses.)
  if (en != null && DICT[id].enAll && !sensesOf(id).includes(en)) {
    throw new Error(
      `wf('${id}', '${al}', '${en}'): '${en}' is not a declared sense of '${id}'. ` +
        `Add it to enAll ("${DICT[id].enAll}") or use one of: ${sensesOf(id).join(', ')}`,
    )
  }
  // If a word has a forms table (nouns we drill in "endings mode"), every inflected
  // surface used in the story MUST be a declared form — this is the completeness
  // guard: an unlisted surface throws at import so the table stays exhaustive.
  if (DICT[id].forms && !formSurfaces(id).includes(al.toLowerCase())) {
    throw new Error(
      `wf('${id}', '${al}'): '${al}' is not a declared form of '${id}'. ` +
        `Add { al: '${al}', tag: '…', gloss: '…' } to its forms table, or fix the surface. ` +
        `Declared: ${formSurfaces(id).join(', ')}`,
    )
  }
  return {
    id,
    al,
    en: en ?? DICT[id].en,
    formTag: DICT[id].forms?.find((form) => form.al.toLowerCase() === al.toLowerCase())?.tag,
  }
}
export const p = (en) => ({ en, paren: true })

// shorthand: build a token line from a compact spec
const L = (...tokens) => tokens

// A natural English reading belongs to the WHOLE Albanian line, never to its
// individual word glosses. Use R() where Albanian and English order diverge or
// where a fluent reading cannot be recovered from the interlinear tokens. The
// tokens remain unchanged and therefore keep their vocabulary-teaching role.
// `englishReadingOf()` in language.js is the only renderer for this metadata.
export const R = (reading, ...tokens) => {
  // R('…', Q(...)) and R('…', L(...)) preserve the original line array and
  // any quote/condition metadata already attached to it. Direct token calls
  // remain the normal authoring form.
  const line = tokens.length === 1 && Array.isArray(tokens[0]) ? tokens[0] : tokens
  return Object.assign(line, { reading })
}

// A source-rooted folk line (a ballad, the Kanun, a tale formula). It is a normal
// token line — every word discoverable and trainable — but carries its attribution
// and a register entry that labels its fidelity as verbatim, inflected, or adapted.
// The game sets it apart visually so the player can inspect that source relationship
// rather than mistaking it for ordinary game prose.
// Composes with when()/unless(): the return value IS the token array.
export const Q = (quoteId, ...tokens) => {
  const q = QUOTES[quoteId]
  if (!q)
    throw new Error(
      `Q('${quoteId}'): not in the quote register. Every folk-quote line needs an ` +
        `entry in src/game/quotes.js documenting its original wording and proof.`,
    )
  return Object.assign(tokens, {
    quote: q.label,
    quoteId,
    quoteGame: q.game,
    // Keep the exact displayed-line translation separate from the translation
    // of the fuller source passage. Comprehension may use only the former.
    quoteGameTranslation: q.gameTranslation,
    quoteSourceTranslation: q.translation,
    // Backward-compatible alias: this now always means the displayed line.
    quoteTranslation: q.gameTranslation,
  })
}

// Conditional story lines — a node.text entry is normally a token line (array), but
// when()/unless() make a line appear only if the player HAS / LACKS a given item or
// companion. This lets a scene react to what walks with you: e.g. with the wolf, a
// hostile encounter resolves "the wolf attacks them" instead of the neutral default.
// Either accepts an array of ids as an AND ("all of these"): when(['night',
// 'fixture:campfire:live'], …) shows the line only at night AND while the fire burns; unless()
// with an array hides it only when ALL are present.
export const when = (itemId, line) => ({ cond: itemId, line })
export const unless = (itemId, line) => ({ cond: itemId, negate: true, line })
// Mixed conditions without ambiguous NAND semantics: every `required` id must
// be present and every `excluded` id must be absent. Keep until([...]) above on
// its historical "hide once ALL are visited" semantics.
export const whenUnless = (required, excluded, line) => ({
  cond: [].concat(required || []),
  none: [].concat(excluded || []),
  line,
})
// from()/notFrom() react to the WAY you entered the scene: gameState tracks the
// node you walked in from (`state.cameFrom`) and exposes it as the virtual item
// `from:<nodeId>`, so an arrival can be narrated as the crossing it was ("you
// cross the tanners' bridge — now you are at the river") while notFrom() keeps
// the plain establishing line for every other way in. Takes one node id or an
// array of them (any match).
const fromCond = (nodeIds) => 'from:' + [].concat(nodeIds).join('|')
export const from = (nodeIds, line) => ({ cond: fromCond(nodeIds), line })
export const notFrom = (nodeIds, line) => ({ cond: fromCond(nodeIds), negate: true, line })
// became()/notBecame() react to the HOUR turning under your feet: gameState
// tracks the time-of-day phase you last acted in (`state.cameFromPhase`) and
// exposes the crossing as the virtual item `became:<phase>`, true only when
// your last choice — a walk, a wait, a `time:` rest-jump — carried the clock
// into that phase. So nightfall can be narrated as it HAPPENS ("nata vjen.")
// while notBecame() keeps the standing description ("është natën.") for a
// scene entered deep inside the phase. Takes one phase id or an array (any).
const becameCond = (phases) => 'became:' + [].concat(phases).join('|')
export const became = (phases, line) => ({
  cond: becameCond(phases),
  line: describesEnvironment('time', line),
})
export const notBecame = (phases, line) => ({ cond: becameCond(phases), negate: true, line })
// FAMILIARITY — scenes that know they've been read (gameState tracks the
// persistent `state.visited` map and exposes it as the virtual items `again`
// and `visited:<nodeId>`). Three wrappers:
//   first(line)       — only while the place is NEW to you: the rich establishing
//                       prose of a first arrival, retired on every later visit so
//                       returns stay slim and the LIVE lines (NPCs, the hour,
//                       your changes) stand out instead of drowning in furniture.
//   again(line)       — only on a RETURN: the world remembers you ("mirë se
//                       erdhe përsëri!"), the scene acknowledges your history.
//   until(dests, line) — a SIGNPOST that retires once every named destination
//                       has been explored: a road you have walked needs no
//                       sentence to sell it (its option auto-reveals — see
//                       optionRevealed in StoryView). Pass one node id or an
//                       array (retires only when ALL are known).
export const first = (line) => ({ cond: 'again', negate: true, line })
export const again = (line) => ({ cond: 'again', line })
export const until = (nodeIds, line) => ({ cond: [].concat(nodeIds).map((n) => 'visited:' + n), negate: true, line })
export const lineOf = (entry) => (Array.isArray(entry) ? entry : entry.line)
// Optional atmosphere may enrich a short card, but it must never force a
// crowded scene onto another page or displace a sentence that teaches or
// unlocks an action. The shared scene-presentation planner is the only place
// that may omit these lines in normal play; Debug always shows them.
export const ambient = (entry, key = null) => {
  const line = lineOf(entry)
  if (!Array.isArray(line)) throw new Error('ambient(): expected a story line or conditional story entry')
  Object.assign(line, { scenePriority: 'ambient', ...(key ? { ambientKey: key } : {}) })
  return entry
}
// the lines actually shown for a node, given has(itemId) -> bool; a cond may be
// an array of ids meaning ALL of them (see when()/unless() above)
export const visibleLines = (node, has) =>
  node.text.filter((e) => {
    if (Array.isArray(e)) return true
    const all = [].concat(e.cond).every(has)
    const none = [].concat(e.none || []).every((id) => !has(id))
    return (e.negate ? !all : all) && none
  }).map(lineOf)

// A greeting is useful because its answer changes with the lived clock. These
// helpers let any social scene become the same small contextual challenge:
// answer with the greeting that fits the present phase, while the other
// greetings remain believable (but wrong) confusers. The ordinary CHOOSE and
// CONFUSE paths still own rewards and heart loss; this is authored content,
// not a parallel quiz state hidden in the component.
const CONTEXT_GREETING_RESPONSES = Object.freeze([
  { id: 'mirmengjes', al: 'mirëmëngjes!', reading: 'Good morning!', correct: ['morning'], line: () => L(w('mirmengjes'), p('!')) },
  { id: 'mirdita', al: 'mirëdita!', reading: 'Good day!', correct: ['day'], line: () => L(w('mirdita'), p('!')) },
  { id: 'mirembrema', al: 'mirëmbrëma!', reading: 'Good evening!', correct: ['evening', 'night'], line: () => L(w('mirembrema'), p('!')) },
  { id: 'natenmire', al: 'natën e mirë!', reading: 'Good night!', correct: [], line: () => L(w('natenmire'), p('!')) },
])

const CONTEXT_GREETING_PERIODS = Object.freeze(['morning', 'day', 'evening', 'night'])

const greetingResponseLine = (response) => R(
  `You answer, “${response.reading}”`,
  w('ti'), wf('thote', 'thua', 'say'), p(':'), ...response.line(),
)

const greetingReplyLines = (challengeId, periods = CONTEXT_GREETING_PERIODS) =>
  CONTEXT_GREETING_RESPONSES.flatMap((response) => response.correct
    .filter((period) => periods.includes(period))
    .map((period) => when(`flag:${challengeId}:${period}`, greetingResponseLine(response))))

const greetingFarewellHintLine = () => R(
  'At night, when you leave, you say, “Good night.”',
  w('naten'), p(','), w('kur'), wf('ik', 'ikën', 'leave'), p(','),
  wf('thote', 'thua', 'say'), p(':'), w('natenmire'), p('.'),
)

const greetingOptionLine = (response) => Object.assign(response.line(), {
  optionReading: response.reading,
  optionReadingAlbanian: response.al,
  optionReadingReview: 'generated-context',
})

const greetingChallengeOptions = (nodeId, challengeId, periods = CONTEXT_GREETING_PERIODS) =>
  periods.flatMap((period) => CONTEXT_GREETING_RESPONSES.map((response) => {
    const correct = response.correct.includes(period)
    return {
      text: greetingOptionLine(response),
      to: nodeId,
      requires: `greeting:${period}`,
      unless: `flag:${challengeId}`,
      durationHours: 0,
      contextGreeting: { challengeId, period, response: response.id, correct },
      ...(correct
        ? { effects: [{ type: 'flag', id: challengeId }, { type: 'flag', id: `${challengeId}:${period}` }] }
        : { confuser: true }),
    }
  }))

// Ordinary carried objects recur across several scenes, so their actions are
// generated from one small capability-aware vocabulary rather than copied into
// the address-pinned story registry. The Albanian and natural English are still
// pinned together and audited; `generated-world-item` records that provenance.
const worldItemAction = (id, albanian, reading, tokens, option = {}) => ({
  ...option,
  text: Object.assign(tokens, {
    optionReading: reading,
    optionReadingAlbanian: albanian,
    optionReadingReview: 'generated-world-item',
  }),
  contextItemAction: { id, kind: option.confuser ? 'confuser' : 'world' },
})

// ---------------------------------------------------------------------------
// STORY GRAPH
// Each node: { id, text: [tokens], options: [{ text:[tokens], to }], end? }
// Answers are kept short and reuse story vocabulary.
// ---------------------------------------------------------------------------
export const START_NODE = 'start'
// the open-world hub you drop back into after a GOOD ending (rather than
// restarting from START_NODE). A good ending may override this with `returnTo`.
export const WORLD_HUB = 'udhekryq'

